ideos','blogs'=>'Blogs & Pages','leads'=>'Leads & CRM','outreach'=>'Outreach','seo'=>'SEO / AEO','revenue'=>'Revenue'] as $k=>$v): ?><a class="<?=($kind===$k)?'active':''?>" href="/dashboard/goliath-assets.php<?=($k?'?kind='.$k:'')?>"><span><?=h($v)?></span><b><?=h($c[$k?:'all']??0)?></b></a><?php endforeach; ?><hr style="border-color:#ffffff18"><a href="/dashboard/scout-contact-workspace.php"><span>Scout CRM</span><b><?=h(($c['homeowner_assigned']??0)+($c['homeowner_queued']??0))?></b></a><a href="/dashboard/scorsese-media-center.php"><span>Scorsese Videos</span><b>›</b></a></aside><main class="panelLite"><h2>Assets <span><?=count($assets)?> shown</span></h2><?php if(!count($assets)): ?><div class="empty"><h2>No assets here yet.</h2><p>V79 is ready. As the local worker completes real asset-contract tasks, they appear here.</p></div><?php endif; ?><div class="grid"><?php foreach($assets as $a): ?><div class="card"><h3><?=h($a['title'])?></h3><div class="meta"><?=h(ucfirst($a['executive_key']))?> · #<?=h($a['id'])?> · <?=h($a['deliverable_type'])?> · <?=h($a['created_at'])?></div><p><?=h(mb_substr(strip_tags($a['output_summary']??''),0,240))?></p><div class="actions"><a class="btn small" href="/dashboard/goliath-deliverables.php?deliverable_id=<?=h($a['id'])?>">Preview</a><?php if(!empty($a['output_url'])):?><a class="btn small" href="<?=h($a['output_url'])?>" target="_blank">Open File</a><?php endif;?><button class="btn small" onclick="revise(<?=h($a['id'])?>,'<?=h($a['executive_key'])?>')">Revise</button><button class="btn small" onclick="alert('Queued for social scheduler next.')">Schedule</button><button class="btn small">Approve</button></div></div><?php endforeach;?></div></main></section></main></div><div class="modal" id="modal"><div class="box"><h2>Revision Request</h2><textarea id="revText" placeholder="Example: Make this more conversion-focused and add a stronger CTA."></textarea><div class="actions"><button class="btn" onclick="sendRev()">Send Revision</button><button class="btn dark" onclick="document.getElementById('modal').style.display='none'">Cancel</button></div><p id="status" class="meta"></p></div></div><script>let cur={id:null,exec:null};function revise(id,exec){cur={id,exec};document.getElementById('modal').style.display='flex';}async function sendRev(){const txt=document.getElementById('revText').value.trim();if(!txt){alert('Add revision instructions.');return;}document.getElementById('status').textContent='Sending...';try{await fetch('/lead-engine/goliath-executive-prompt.php',{method:'POST',body:new URLSearchParams({key:<?=json_encode($key)?>,prompt:'@'+cur.exec+' Revise asset #'+cur.id+': '+txt})});document.getElementById('status').textContent='Revision sent.';}catch(e){document.getElementById('status').textContent='Could not send.';}}</script></body></html>